where first_results_at is null and event_id in ('66338','66339','66340','66341','66342','66343','66344','66345','66346','66347','66348','66349','66951','66949','66950','66350','66351','66352','66353','66354','66355','67511','66356','66357','66358','66359','66360','66361','66362','66363','66364','66365','66366','67539','67654','67678','68314','67533','67534','67959','68103','68227','67741','68115','68406','67535','67644','67695','68687','66954','66952','66953','67510','67802','67807','68114','68478','68811','67703','67748','68242','68118','68316','68407','68472','68676','68738','67606','67879','68437','68813','67509','67536','67704','68204','68404','67655','68104','68116','68317','69395','67540','67609','67743','68937','67537','68119','68226','68315','68688','69000','67538','67679','67696','67806','69264','67742','67970','68205','68438','68479','69396','69397','64989','64991','64990','67960','68408','68677','68686','68739','67607','67801','67803','67808','68017','69010','72041','72042','72087','72095','72096');
